import Foundation
import simd

// MARK: - Brush model

/// The stamp a brush paints with.
public enum BrushTip: Codable, Hashable, Sendable {
    /// An analytic, perfectly anti-aliased disc whose edge softness is `BrushPreset.hardness`.
    case round
    /// A procedural texture generated by `BrushTextureLibrary` (e.g. "charcoal", "splatter").
    case builtin(String)
    /// A custom greyscale PNG (white = paint). Imported .abr tips end up here.
    case image(Data)
}

/// How a grain texture is applied (Procreate's terms).
public enum GrainMode: String, Codable, CaseIterable, Sendable {
    /// The grain is part of the stamp: each dab gets its own patch of texture.
    case moving
    /// The grain is fixed to the canvas, like paper under the pencil.
    case texturized
}

public struct GrainSettings: Codable, Hashable, Sendable {
    public var source: BrushTip = .builtin("paper")
    /// Canvas pixels per grain texel (1 = native resolution).
    public var scale: Float = 1
    /// 0 = no grain, 1 = full grain.
    public var depth: Float = 0.7
    public var mode: GrainMode = .texturized
    public init(source: BrushTip = .builtin("paper"), scale: Float = 1, depth: Float = 0.7, mode: GrainMode = .texturized) {
        self.source = source; self.scale = scale; self.depth = depth; self.mode = mode
    }
}

/// How the secondary tip of a dual brush combines with the primary one (Photoshop's Dual Brush).
public enum DualBlend: String, Codable, CaseIterable, Sendable {
    case multiply, darken, subtract, height
    var shaderIndex: UInt32 { UInt32(Self.allCases.firstIndex(of: self)! + 1) }
}

public struct DualBrushSettings: Codable, Hashable, Sendable {
    public var tip: BrushTip = .builtin("splatter")
    /// Secondary tip size relative to the primary.
    public var scale: Float = 0.5
    /// Random offset of the secondary tip, 0…1.
    public var scatter: Float = 0.5
    public var depth: Float = 1
    public var blend: DualBlend = .multiply
    public init(tip: BrushTip = .builtin("splatter"), scale: Float = 0.5, scatter: Float = 0.5, depth: Float = 1,
                blend: DualBlend = .multiply) {
        self.tip = tip; self.scale = scale; self.scatter = scatter; self.depth = depth; self.blend = blend
    }
}

public enum RotationMode: String, Codable, CaseIterable, Sendable {
    /// Stamp angle stays at `BrushPreset.angle`.
    case fixed
    /// Stamp turns with the direction of the stroke.
    case followStroke
    /// Stamp turns with Apple Pencil's azimuth (which way the pencil leans).
    case followAzimuth
}

/// A complete brush definition — everything Brush Studio can edit. Codable, so it doubles as the
/// `.paperbrush` file format.
public struct BrushPreset: Codable, Identifiable, Hashable, Sendable {
    public var id = UUID()
    public var name: String
    public var category: String
    public var author = "Paper"

    // Shape
    public var tip: BrushTip = .round
    /// Edge hardness of the analytic round tip, 0 (airbrush) … 1 (crisp).
    public var hardness: Float = 0.85
    /// Distance between dabs as a fraction of the diameter.
    public var spacing: Float = 0.08
    /// Stamp angle in degrees.
    public var angle: Float = 0
    /// 1 = circle; smaller values squash the stamp into an ellipse.
    public var roundness: Float = 1
    public var rotationMode: RotationMode = .fixed
    public var randomFlip = false

    // Texture
    public var grain: GrainSettings?
    public var dual: DualBrushSettings?

    // Size & opacity
    /// Default diameter in canvas pixels.
    public var defaultSize: Float = 24
    public var minSize: Float = 1
    public var maxSize: Float = 600
    public var defaultOpacity: Float = 1
    /// How much paint each dab deposits (opacity caps the whole stroke; flow builds up within it).
    public var flow: Float = 1

    // Apple Pencil response (amounts are 0…1)
    public var pressureCurve: ResponseCurve = .linear
    public var pressureSize: Float = 0.8
    public var pressureOpacity: Float = 0
    public var pressureFlow: Float = 0
    public var tiltCurve: ResponseCurve = .linear
    /// Lay the pencil flat → the stamp grows (up to 3×).
    public var tiltSize: Float = 0
    /// Lay the pencil flat → lighter paint.
    public var tiltOpacity: Float = 0
    /// Lay the pencil flat → the stamp flattens into an ellipse (pencil shading).
    public var tiltRoundness: Float = 0
    /// Faster strokes get thinner (positive) or thicker (negative); also simulates pressure for a mouse.
    public var velocitySize: Float = 0

    // Jitter
    public var sizeJitter: Float = 0
    /// 0…1 → up to ±180°.
    public var angleJitter: Float = 0
    /// Random sideways offset as a fraction of the diameter.
    public var scatter: Float = 0
    /// Dabs per spacing step.
    public var count = 1
    public var opacityJitter: Float = 0

    // Stabilisation
    /// Procreate StreamLine: a "pulled string" that irons out wobble (0…1).
    public var streamline: Float = 0.25
    /// Averages the last few points (0…1); smoother but laggier.
    public var stabilization: Float = 0
    /// Stroke starts thin and swells over this many diameters (0 = off).
    public var startTaper: Float = 0

    // Colour dynamics
    public var hueJitter: Float = 0
    public var saturationJitter: Float = 0
    public var brightnessJitter: Float = 0
    /// Signed −1…1: light pressure shifts hue / saturation / brightness by this much.
    public var pressureHue: Float = 0
    public var pressureSaturation: Float = 0
    public var pressureBrightness: Float = 0

    // Wet media
    /// Darker, pooled edges like watercolour (0…1).
    public var wetEdges: Float = 0
    /// Picks up the colour already on the layer (0…1).
    public var wetMix: Float = 0

    public init(name: String, category: String) {
        self.name = name
        self.category = category
    }

    /// A copy with a fresh identity (for "Duplicate brush").
    public func duplicated(named newName: String? = nil) -> BrushPreset {
        var b = self
        b.id = UUID()
        b.name = newName ?? name + " Copy"
        return b
    }
}

// MARK: - Stroke input

/// One sample of pointer input in canvas pixel coordinates.
public struct StrokeSample: Equatable, Sendable {
    public var position: SIMD2<Float>
    /// 0…1. Mice and trackpads report 1.
    public var pressure: Float
    /// Radians: π/2 = pencil upright, 0 = lying flat.
    public var altitude: Float
    /// Radians in canvas space: the direction the pencil leans towards.
    public var azimuth: Float
    public var timestamp: TimeInterval

    public init(position: SIMD2<Float>, pressure: Float = 1, altitude: Float = .pi / 2, azimuth: Float = 0,
                timestamp: TimeInterval = 0) {
        self.position = position; self.pressure = pressure; self.altitude = altitude
        self.azimuth = azimuth; self.timestamp = timestamp
    }

    static func lerp(_ a: StrokeSample, _ b: StrokeSample, _ t: Float) -> StrokeSample {
        var azimuthDelta = b.azimuth - a.azimuth
        if azimuthDelta > .pi { azimuthDelta -= 2 * .pi }
        if azimuthDelta < -.pi { azimuthDelta += 2 * .pi }
        return StrokeSample(position: a.position + (b.position - a.position) * t,
                            pressure: a.pressure + (b.pressure - a.pressure) * t,
                            altitude: a.altitude + (b.altitude - a.altitude) * t,
                            azimuth: a.azimuth + azimuthDelta * t,
                            timestamp: a.timestamp + (b.timestamp - a.timestamp) * Double(t))
    }
}

/// One stamp, laid out exactly like the MSL `Dab` struct (64 bytes).
public struct Dab: Equatable {
    /// Straight (not premultiplied) colour; `.w` is this dab's opacity cap.
    public var color: SIMD4<Float>
    public var center: SIMD2<Float>
    public var grainOffset: SIMD2<Float> = .zero
    public var dualOffset: SIMD2<Float> = .zero
    public var radius: Float
    public var angle: Float = 0
    public var roundness: Float = 1
    public var flow: Float = 1
    public var dualAngle: Float = 0
    public var flip: Float = 1

    /// Pixel bounds the dab can touch.
    var bounds: IntRect {
        let r = radius + 2
        return IntRect(covering: center - SIMD2(r, r), center + SIMD2(r, r))
    }
}

// MARK: - Random numbers

/// Small, fast, seedable generator (SplitMix64) so strokes are reproducible.
public struct SplitMix64: RandomNumberGenerator {
    private var state: UInt64
    public init(seed: UInt64) { state = seed }
    public mutating func next() -> UInt64 {
        state &+= 0x9E37_79B9_7F4A_7C15
        var z = state
        z = (z ^ (z >> 30)) &* 0xBF58_476D_1CE4_E5B9
        z = (z ^ (z >> 27)) &* 0x94D0_49BB_1331_11EB
        return z ^ (z >> 31)
    }
    /// Uniform in [0, 1).
    public mutating func unit() -> Float { Float(next() >> 40) / Float(1 << 24) }
    /// Uniform in [−1, 1).
    public mutating func signed() -> Float { unit() * 2 - 1 }
}

// MARK: - Stabiliser

/// StreamLine ("pulled string") plus moving-average stabilisation.
struct StrokeStabilizer {
    let stringLength: Float
    let windowSize: Int
    private var pulled: SIMD2<Float>?
    private var smoothedPressure: Float = 0
    private var window: [SIMD2<Float>] = []
    private(set) var lastRaw: StrokeSample?

    /// `viewScale` is screen points per canvas pixel, so the string feels the same at any zoom.
    init(streamline: Float, stabilization: Float, viewScale: Float) {
        stringLength = max(0, streamline) * 40 / max(viewScale, 0.05)
        windowSize = 1 + Int((max(0, stabilization) * 24).rounded())
    }

    mutating func process(_ s: StrokeSample) -> StrokeSample {
        lastRaw = s
        var out = s
        if let p = pulled {
            let d = s.position - p
            let len = simd_length(d)
            pulled = len > stringLength ? p + d * ((len - stringLength) / len) : p
            smoothedPressure += (s.pressure - smoothedPressure) * 0.35
        } else {
            pulled = s.position
            smoothedPressure = s.pressure
        }
        out.position = pulled!
        if stringLength > 0 { out.pressure = smoothedPressure }
        if windowSize > 1 {
            window.append(out.position)
            if window.count > windowSize { window.removeFirst(window.count - windowSize) }
            out.position = window.reduce(SIMD2<Float>.zero, +) / Float(window.count)
        }
        return out
    }

    /// Points that walk the smoothed position the rest of the way to where the pen lifted.
    mutating func catchUp() -> [StrokeSample] {
        guard let raw = lastRaw, let p = pulled else { return [] }
        let start = window.isEmpty ? p : window.reduce(SIMD2<Float>.zero, +) / Float(window.count)
        let dist = simd_distance(start, raw.position)
        guard dist > 0.5 else { return [] }
        let steps = min(12, max(1, Int(dist / 4)))
        return (1...steps).map { i in
            var s = raw
            s.position = start + (raw.position - start) * (Float(i) / Float(steps))
            s.pressure = smoothedPressure
            return s
        }
    }
}

// MARK: - Dab generator

/// Turns stabilised samples into evenly spaced dabs: centripetal Catmull-Rom interpolation between
/// samples, arc-length resampling at the brush spacing, and per-dab dynamics (pressure, tilt,
/// velocity, jitter, scatter, colour dynamics, taper).
struct DabGenerator {
    let brush: BrushPreset
    /// User's size slider (diameter, px).
    let baseSize: Float
    /// Straight Display P3 base colour.
    let baseColor: SIMD3<Float>
    private let baseHSB: SIMD3<Float>
    private var rng: SplitMix64
    private var points: [StrokeSample] = []
    private var emitted = 0
    private var distanceToNext: Float = 0
    private var travelled: Float = 0
    private var lastDirection = SIMD2<Float>(1, 0)
    private var speed: Float = 0

    init(brush: BrushPreset, size: Float, color: SIMD3<Float>, seed: UInt64) {
        self.brush = brush
        self.baseSize = max(0.5, size)
        self.baseColor = color
        self.baseHSB = ColorMath.rgbToHSB(color)
        self.rng = SplitMix64(seed: seed)
    }

    /// Adds a stabilised sample; returns the dabs that are now final.
    mutating func add(_ s: StrokeSample) -> [Dab] {
        if let last = points.last {
            let d = simd_distance(last.position, s.position)
            guard d > 0.01 else { return [] }
            let dt = Float(max(s.timestamp - last.timestamp, 1.0 / 240.0))
            speed += (d / dt - speed) * 0.3
        }
        points.append(s)
        if points.count == 1 {
            // First contact: one dab right away so taps leave a mark.
            distanceToNext = spacing(for: s)
            return makeDabs(at: s, direction: lastDirection)
        }
        var out: [Dab] = []
        while emitted + 2 < points.count {
            out += emitSegment(emitted)
            emitted += 1
        }
        return out
    }

    /// Flushes the remaining segments at the end of a stroke.
    mutating func finish() -> [Dab] {
        var out: [Dab] = []
        while emitted + 1 < points.count {
            out += emitSegment(emitted)
            emitted += 1
        }
        return out
    }

    private func spacing(for s: StrokeSample) -> Float {
        max(0.35, brush.spacing * size(for: s, includeJitter: false))
    }

    /// Centripetal Catmull-Rom through p0…p3, evaluated between p1 and p2.
    private static func catmullRom(_ p0: SIMD2<Float>, _ p1: SIMD2<Float>, _ p2: SIMD2<Float>, _ p3: SIMD2<Float>,
                                   _ t: Float) -> SIMD2<Float> {
        func knot(_ a: SIMD2<Float>, _ b: SIMD2<Float>) -> Float { max(pow(simd_distance(a, b), 0.5), 1e-4) }
        let t0: Float = 0
        let t1 = t0 + knot(p0, p1)
        let t2 = t1 + knot(p1, p2)
        let t3 = t2 + knot(p2, p3)
        let tt = t1 + (t2 - t1) * t
        let a1 = p0 * ((t1 - tt) / (t1 - t0)) + p1 * ((tt - t0) / (t1 - t0))
        let a2 = p1 * ((t2 - tt) / (t2 - t1)) + p2 * ((tt - t1) / (t2 - t1))
        let a3 = p2 * ((t3 - tt) / (t3 - t2)) + p3 * ((tt - t2) / (t3 - t2))
        let b1 = a1 * ((t2 - tt) / (t2 - t0)) + a2 * ((tt - t0) / (t2 - t0))
        let b2 = a2 * ((t3 - tt) / (t3 - t1)) + a3 * ((tt - t1) / (t3 - t1))
        return b1 * ((t2 - tt) / (t2 - t1)) + b2 * ((tt - t1) / (t2 - t1))
    }

    private mutating func emitSegment(_ i: Int) -> [Dab] {
        let s1 = points[i], s2 = points[i + 1]
        let p0 = points[max(i - 1, 0)].position
        let p3 = points[min(i + 2, points.count - 1)].position
        // Extrapolate missing end controls so the ends stay straight.
        let c0 = i == 0 ? s1.position * 2 - s2.position : p0
        let c3 = i + 2 >= points.count ? s2.position * 2 - s1.position : p3

        let chord = simd_distance(s1.position, s2.position)
        let steps = max(4, min(256, Int(chord / 1.5)))
        var out: [Dab] = []
        var prev = s1.position
        for k in 1...steps {
            let t = Float(k) / Float(steps)
            let pos = Self.catmullRom(c0, s1.position, s2.position, c3, t)
            let seg = pos - prev
            var segLen = simd_length(seg)
            guard segLen > 1e-5 else { continue }
            let dir = seg / segLen
            lastDirection = dir
            var walked: Float = 0
            while segLen >= distanceToNext {
                walked += distanceToNext
                segLen -= distanceToNext
                travelled += distanceToNext
                let u = (t - 1 / Float(steps)) + (walked / max(simd_length(seg), 1e-5)) / Float(steps)
                var sample = StrokeSample.lerp(s1, s2, min(max(u, 0), 1))
                sample.position = prev + dir * walked
                out += makeDabs(at: sample, direction: dir)
                distanceToNext = spacing(for: sample)
            }
            distanceToNext -= segLen
            travelled += segLen
            prev = pos
        }
        return out
    }

    private func tiltAmount(_ s: StrokeSample) -> Float {
        // 0 when the pencil is upright, 1 when it lies flat.
        let flat = 1 - min(max(s.altitude / (.pi / 2), 0), 1)
        return brush.tiltCurve.value(at: flat)
    }

    private func size(for s: StrokeSample, includeJitter: Bool) -> Float {
        let pc = brush.pressureCurve.value(at: s.pressure)
        var size = baseSize * (1 - brush.pressureSize + brush.pressureSize * pc)
        size *= 1 + brush.tiltSize * 2 * tiltAmount(s)
        if brush.velocitySize != 0 {
            let v = min(speed / 3000, 1)
            size *= max(0.1, 1 - brush.velocitySize * v)
        }
        if brush.startTaper > 0 {
            let taperLength = brush.startTaper * baseSize * 6
            if travelled < taperLength { size *= 0.15 + 0.85 * (travelled / taperLength) }
        }
        return min(max(size, 0.5), max(brush.maxSize, baseSize) * 3)
    }

    private mutating func makeDabs(at s: StrokeSample, direction: SIMD2<Float>) -> [Dab] {
        let pc = brush.pressureCurve.value(at: s.pressure)
        let tilt = tiltAmount(s)
        var dabs: [Dab] = []
        for _ in 0..<max(1, brush.count) {
            var diameter = size(for: s, includeJitter: true)
            if brush.sizeJitter > 0 { diameter *= 1 - brush.sizeJitter * rng.unit() }
            let radius = max(0.5, diameter / 2)

            var center = s.position
            if brush.scatter > 0 {
                let normal = SIMD2<Float>(-direction.y, direction.x)
                center += normal * (rng.signed() * brush.scatter * diameter)
                center += direction * (rng.signed() * brush.scatter * diameter * 0.5)
            }

            var angle = brush.angle * .pi / 180
            switch brush.rotationMode {
            case .fixed: break
            case .followStroke: angle += atan2(direction.y, direction.x)
            case .followAzimuth: angle += s.azimuth
            }
            if brush.angleJitter > 0 { angle += rng.signed() * brush.angleJitter * .pi }

            let roundness = max(0.05, brush.roundness * (1 - brush.tiltRoundness * 0.85 * tilt))

            var opacityCap = 1 - brush.pressureOpacity + brush.pressureOpacity * pc
            opacityCap *= 1 - brush.tiltOpacity * tilt
            var flow = brush.flow * (1 - brush.pressureFlow + brush.pressureFlow * pc)
            if brush.opacityJitter > 0 { flow *= 1 - brush.opacityJitter * rng.unit() }

            var dab = Dab(color: SIMD4(dabColor(pressure: pc), min(max(opacityCap, 0), 1)),
                          center: center, radius: radius)
            dab.angle = angle
            dab.roundness = roundness
            dab.flow = min(max(flow, 0), 1)
            dab.grainOffset = SIMD2(rng.unit(), rng.unit())
            if let dual = brush.dual {
                dab.dualOffset = SIMD2(rng.signed(), rng.signed()) * dual.scatter
                dab.dualAngle = rng.unit() * 2 * .pi
            }
            if brush.randomFlip && rng.unit() < 0.5 { dab.flip = -1 }
            dabs.append(dab)
        }
        return dabs
    }

    private mutating func dabColor(pressure pc: Float) -> SIMD3<Float> {
        let dynamic = brush.hueJitter + brush.saturationJitter + brush.brightnessJitter
            + abs(brush.pressureHue) + abs(brush.pressureSaturation) + abs(brush.pressureBrightness)
        guard dynamic > 0 else { return baseColor }
        var h = baseHSB.x, s = baseHSB.y, b = baseHSB.z
        let light = 1 - pc
        h += brush.pressureHue * light * 0.5
        s *= 1 - brush.pressureSaturation * light
        b *= 1 - brush.pressureBrightness * light
        if brush.hueJitter > 0 { h += rng.signed() * brush.hueJitter * 0.5 }
        if brush.saturationJitter > 0 { s += rng.signed() * brush.saturationJitter }
        if brush.brightnessJitter > 0 { b += rng.signed() * brush.brightnessJitter }
        h = h - floor(h)
        return ColorMath.hsbToRGB(SIMD3(h, min(max(s, 0), 1), min(max(b, 0), 1)))
    }
}

// MARK: - Colour helpers

public enum ColorMath {
    /// RGB (0…1) → hue (0…1), saturation, brightness.
    public static func rgbToHSB(_ c: SIMD3<Float>) -> SIMD3<Float> {
        let maxC = max(c.x, c.y, c.z), minC = min(c.x, c.y, c.z)
        let delta = maxC - minC
        var h: Float = 0
        if delta > 1e-6 {
            if maxC == c.x { h = (c.y - c.z) / delta }
            else if maxC == c.y { h = 2 + (c.z - c.x) / delta }
            else { h = 4 + (c.x - c.y) / delta }
            h /= 6
            if h < 0 { h += 1 }
        }
        let s = maxC > 1e-6 ? delta / maxC : 0
        return SIMD3(h, s, maxC)
    }

    public static func hsbToRGB(_ hsb: SIMD3<Float>) -> SIMD3<Float> {
        let h = (hsb.x - floor(hsb.x)) * 6, s = hsb.y, v = hsb.z
        let i = Int(h) % 6
        let f = h - floor(h)
        let p = v * (1 - s), q = v * (1 - s * f), t = v * (1 - s * (1 - f))
        switch i {
        case 0: return SIMD3(v, t, p)
        case 1: return SIMD3(q, v, p)
        case 2: return SIMD3(p, v, t)
        case 3: return SIMD3(p, q, v)
        case 4: return SIMD3(t, p, v)
        default: return SIMD3(v, p, q)
        }
    }

    /// Display P3 luminance of gamma-encoded RGB.
    public static func luma(_ c: SIMD3<Float>) -> Float {
        simd_dot(c, SIMD3(0.2289746, 0.6917385, 0.0792869))
    }

    /// "#RRGGBB" for a straight colour.
    public static func hex(_ c: SIMD3<Float>) -> String {
        let v = simd_clamp(c, .zero, SIMD3(repeating: 1)) * 255
        return String(format: "#%02X%02X%02X", Int(v.x.rounded()), Int(v.y.rounded()), Int(v.z.rounded()))
    }

    public static func fromHex(_ s: String) -> SIMD3<Float>? {
        var t = s.trimmingCharacters(in: .whitespaces)
        if t.hasPrefix("#") { t.removeFirst() }
        guard t.count == 6, let n = UInt32(t, radix: 16) else { return nil }
        return SIMD3(Float((n >> 16) & 0xFF), Float((n >> 8) & 0xFF), Float(n & 0xFF)) / 255
    }
}
